using System.Diagnostics;
using System.Numerics;
using Autonomous146;
using SharedWorldSpeedway;
namespace Robust150;
public sealed record Options150(bool Enabled=false,int Laps=3,int Portfolio=3,int Candidates=36,bool RobustScreen=true,bool Feedback=false,bool SpatialFeedback=false,bool AcceptedOperatingPoint=false,bool JointFeedback=false);
public sealed record Candidate150(Tape150 Tape,bool Robust,Tape150? Challenge,string Reason,Tape150? Anchor=null);
public sealed record Summary150(string Origin,bool Legal,bool Robust,double? Seconds,double EndReference,double MinimumGap,double Sweep,double Beta,double Yaw,string Reason,int Actions,FreeRacingAction[] Sequence);
public sealed record Review150(double Time,State146 Observed,double Goal,double SafetyGoal,string Reason,int Considered,int Legal,int Robust,int Inherited,int Pruned,Summary150[] Alternatives,FreeRacingAction[]? Selected,double? Arrival,Safety146? Certificate,Safety146? Independent,FreeRacingPoint[]? ForecastTrace,object Counts,double CpuSeconds);
/// <summary>Default OFF. Joint action edits at future physical/geometry events; full propagation and independent certification.</summary>
public sealed class Planner150{
 public Options150 Options {get;}public Runtime150 Runtime {get;}public Review150? Last {get;private set;}public Tape150? SelectedAnchor {get;private set;}
 readonly Action guard;readonly ErrorVector150 measuredError;readonly List<Candidate150> portfolio=new();double nextSearch;int? lastSegment;
 public Planner150(RiderSpec spec,bool separated,Options150? options=null,Action? guard=null,ErrorVector150? error=null){Options=options??new();if(!Options.Enabled)throw new InvalidOperationException("Planner150 is OFF by default.");if(Options.Laps is <1 or >3||Options.Portfolio is <1 or >3||Options.Candidates is <6 or >60)throw new ArgumentException("Bounded planner required.");this.guard=guard??(()=>{});Runtime=new(spec,separated,spatial:Options.SpatialFeedback,accepted:Options.AcceptedOperatingPoint,joint:Options.JointFeedback);
  // Measured model-error vector only. No saved action, target line or future native state is loaded.
  measuredError=error??Program150.Read<ErrorVector150[]>(Program150.Doc+"/model-errors.json").Single(x=>x.Model==(separated?"B":"A"));
 }
 public void InitializeDiagnosticTape(Tape150 tape){if(portfolio.Count>0)throw new InvalidOperationException("Initialize once");portfolio.Add(new(tape,false,null,"diagnostic incumbent",tape));}
 public State146 ChallengeForDiagnostics(State146 state,int sign)=>ErrorState(state,sign);
 State146 ErrorState(State146 state,int sign){var p=state.Input.Rider;var e=measuredError;var scale=sign*Math.Min(1,p.Speed/RearWheelParameters.Default.LowSpeedMetersPerSecond);var pos=p.Position+new Vector2(e.DX,e.DY)*(float)scale;var road=Runtime.Frame.Project(pos);var reference=p.TotalReferenceMeters+Runtime.Frame.UnwrapDelta(p.Road.ReferenceMeters,road.ReferenceMeters);var rider=p with{Position=pos,Velocity=p.Velocity+new Vector2(e.DVX,e.DVY)*(float)scale,Heading=p.Heading+(float)(e.Heading*scale),AngularVelocity=p.AngularVelocity+(float)(e.Yaw*scale),Road=road,TotalReferenceMeters=reference,Context=Runtime.Frame.Context(road,reference)};return new(state.Input with{Rider=rider,Omega=Math.Max(0,state.Input.Omega+e.Wheel*scale)},state.CrankOmega+e.Crank*scale);}
 Candidate150 Assess(Tape150 tape,State146 start,Tape150? anchor=null){anchor??=tape;if(!tape.Safety.Legal)return new(tape,false,tape,tape.Safety.Reason,anchor);if(!Options.RobustScreen)return new(tape,true,null,"nominal-only diagnostic",anchor);
  foreach(var sign in new[]{1,-1}){var challenge=Options.Feedback?Feedback150.Evaluate(Runtime,ErrorState(start,sign),anchor,tape.Goal,tape.SafetyGoal,"measured-error-"+sign,guard):Rollout150.Evaluate(Runtime,ErrorState(start,sign),tape.Actions,tape.Goal,tape.SafetyGoal,"measured-error-"+sign,guard:guard);if(!challenge.Safety.Legal)return new(tape,false,challenge,"measured-error "+challenge.Safety.Reason,anchor);}return new(tape,true,null,"two measured-error scenarios legal",anchor);
 }
 public static FreeRacingAction[] DiverseActions(State146 at,FreeRacingAction root){var original=FreeLearningController.Actions(at.Input,Controller143.Policy,true);var angles=original.Select(x=>x.SteeringRadians).Distinct().Order().ToArray();var expanded=angles.Concat(angles.Zip(angles.Skip(1),(a,b)=>(a+b)/2)).Distinct().OrderBy(x=>Math.Abs(x-root.SteeringRadians)).ThenBy(x=>x).Take(5).ToArray();var drives=original.Select(x=>x.Drive).Distinct().Order().ToArray();return expanded.SelectMany(s=>drives.Select(d=>new FreeRacingAction(s,d))).Where(x=>x!=root).ToArray();}
 static IEnumerable<Candidate150> Order(IEnumerable<Candidate150> list)=>list.OrderBy(x=>!x.Tape.Safety.Legal).ThenBy(x=>!x.Robust).ThenBy(x=>x.Tape.Safety.Legal?x.Tape.Seconds:0).ThenByDescending(x=>x.Tape.Safety.Legal?0:x.Tape.End.Input.Rider.TotalReferenceMeters).ThenByDescending(x=>x.Tape.Safety.MinimumGapMeters);
 int[] Epochs(Candidate150 root){var tape=root.Challenge??root.Tape;var candidates=new List<int>();
  if(!root.Robust){var failure=tape.Points.FirstOrDefault(p=>!Planner146.Check(new[]{p},.1).Legal);var time=failure?.Time??tape.End.Input.Time;candidates.Add(Math.Max(0,(int)Math.Floor((time-tape.CreatedAt-.24)/.2)-3));}
  // Geometry provides event times, not an offset/line. Include approach, middle and exit events.
  for(int k=1;k<root.Tape.States.Length;k++){var before=root.Tape.States[k-1].Input.Rider;var after=root.Tape.States[k].Input.Rider;if(before.Road.Segment!=after.Road.Segment)candidates.Add(Math.Max(0,k-3));}
  candidates.Add(0);return candidates.Distinct().Where(k=>k<root.Tape.Actions.Length).Take(4).ToArray();
 }
 IEnumerable<(int Epoch,FreeRacingAction Action)> PhaseProposals(Candidate150 root){var epochs=Epochs(root);var choices=epochs.Select(k=>DiverseActions(root.Tape.States[k],root.Tape.Actions[k])).ToArray();for(int rank=0;rank<choices.Select(x=>x.Length).DefaultIfEmpty(0).Max();rank++)for(int j=0;j<epochs.Length;j++)if(rank<choices[j].Length)yield return(epochs[j],choices[j][rank]);}
 public Decision144 Choose(FreeRacingInput input,CrankClutch144 crank){var process=Process.GetCurrentProcess();var began=process.TotalProcessorTime;guard();Runtime.Begin(input.Time);long f0=Runtime.Forecasts,c0=Runtime.Contacts;var start=new State146(input with{NextReview=input.Time},crank.Omega);var previous=portfolio.FirstOrDefault(p=>p.Tape.Goal>input.Rider.TotalReferenceMeters+.001);var goal=previous?.Tape.Goal??Planner146.Goal(Runtime.Frame,input.Rider.TotalReferenceMeters,Options.Laps);var safetyGoal=Planner146.Goal(Runtime.Frame,goal+.005,Options.Laps);var pool=new List<Candidate150>();int inherited=0,pruned=0;
  foreach(var old in portfolio.Where(p=>Math.Abs(p.Tape.Goal-goal)<1e-7||Options.Feedback&&p.Tape.SafetyGoal>=goal)){var anchor=old.Anchor??old.Tape;var shift=(int)Math.Round((input.Time-anchor.CreatedAt)/.2);if(shift>=anchor.Actions.Length)continue;var extend=old.Tape.SafetyGoal<safetyGoal;var tape=Options.Feedback?Feedback150.Evaluate(Runtime,start,anchor,goal,safetyGoal,"retained-tape",guard,extend):Rollout150.Evaluate(Runtime,start,anchor.Actions.Skip(shift).ToArray(),goal,safetyGoal,"retained-tape",guard:guard);pool.Add(Assess(tape,start,extend?tape:anchor));inherited++;}
  if(!pool.Any(x=>x.Robust)){using var role=Runtime.Operation("fresh-K1-seed");var seed=Rollout150.Evaluate(Runtime,start,Array.Empty<FreeRacingAction>(),goal,safetyGoal,"endogenous-K1",generateTail:true,guard:guard);pool.Add(Assess(seed,start));}
  var search=!pool.Any(x=>x.Robust)||input.Time>=nextSearch-1e-8||lastSegment!=input.Rider.Road.Segment;
  if(search){using var role=Runtime.Operation("beam-event-search150");
   try{for(int depth=0;depth<2&&pool.Count<Options.Candidates;depth++){
    var stageLimit=(depth+1)*Options.Candidates/2;var roots=Order(pool).Take(2).ToArray();foreach(var root in roots)foreach(var proposal in PhaseProposals(root)){
     var epoch=proposal.Epoch;var action=proposal.Action;var at=root.Tape.States[epoch];{
      guard();if(pool.Count>=Options.Candidates||Runtime.Forecasts-f0>6500||Runtime.Contacts-c0>530000)goto SearchDone;
      if(pool.Count>=stageLimit)goto NextDepth;
      // Optimistic force/geometry bound: all mu*Fz available for speed, Jacobian>=.9 on frozen G0.
      var best=Order(pool.Where(x=>x.Robust)).FirstOrDefault();var distance=Math.Max(0,goal-at.Input.Rider.TotalReferenceMeters)*.9;var acceleration=LoadBasedTyreParameters.Default.ReferenceFrictionCoefficient*LoadBasedTyreGrip.GravityMetersPerSecondSquared;var lower=at.Input.Time-input.Time+(Math.Sqrt(at.Input.Rider.Speed*at.Input.Rider.Speed+2*acceleration*distance)-at.Input.Rider.Speed)/acceleration;if(best is not null&&lower>=best.Tape.Seconds){pruned++;continue;}
      var actions=root.Tape.Actions.ToArray();for(int j=epoch;j<Math.Min(epoch+2,actions.Length);j++)actions[j]=action;var candidate=Rollout150.Evaluate(Runtime,start,actions,goal,safetyGoal,$"event-{depth}-{epoch}",generateTail:true,guard:guard);pool.Add(Assess(candidate,start));
     }
    }
   NextDepth:;}}catch(PlanningBudget146){/* No uncertified fallback; only already complete robust plans remain eligible. */}
  SearchDone:nextSearch=input.Time+1.2;}
  var feasible=Order(pool.Where(x=>x.Robust&&x.Tape.Safety.Legal)).ToArray();var selected=feasible.FirstOrDefault();var incumbent=feasible.FirstOrDefault(x=>x.Tape.Origin=="retained-tape");if(incumbent is not null&&selected is not null&&incumbent.Tape.Seconds<=selected.Tape.Seconds+.02)selected=incumbent;Safety146? independent=null;var reason=selected is null?"abstain: no robust complete continuation":selected.Tape.Origin;
  if(selected is not null){using var role=Runtime.Operation("independent_preflight");var check=Options.Feedback?Feedback150.Evaluate(Runtime,start,selected.Anchor!,goal,safetyGoal,"independent-full",guard):Rollout150.Evaluate(Runtime,start,selected.Tape.Actions,goal,safetyGoal,"independent-full",guard:guard);independent=check.Safety;if(!independent.Legal||!check.Actions.SequenceEqual(selected.Tape.Actions)){reason="abstain: independent full certificate/command contract "+independent.Reason;selected=null;}}
  SelectedAnchor=selected?.Anchor;if(selected is not null){portfolio.Clear();var distinct=new HashSet<string>();foreach(var candidate in feasible.Prepend(selected)){var key=string.Join(';',candidate.Tape.Actions.Select(a=>$"{a.SteeringRadians:R},{a.Drive:R}"));if(distinct.Add(key))portfolio.Add(candidate);if(portfolio.Count==Options.Portfolio)break;}lastSegment=input.Rider.Road.Segment;}
  var elapsed=(process.TotalProcessorTime-began).TotalSeconds;Last=new(input.Time,start,goal,safetyGoal,reason,pool.Count,pool.Count(x=>x.Tape.Safety.Legal),pool.Count(x=>x.Robust),inherited,pruned,pool.Select(x=>new Summary150(x.Tape.Origin,x.Tape.Safety.Legal,x.Robust,x.Tape.Arrival is null?null:x.Tape.Seconds,x.Tape.End.Input.Rider.TotalReferenceMeters,x.Tape.Safety.MinimumGapMeters,x.Tape.Safety.SweepLowerBoundMeters,x.Tape.Safety.MaximumBetaDegrees,x.Tape.Safety.MaximumYawRate,x.Reason,x.Tape.Actions.Length,x.Tape.Actions)).ToArray(),selected?.Tape.Actions,selected?.Tape.Arrival,selected?.Tape.Safety,independent,selected?.Tape.Points.Where((_,k)=>k%10==0).ToArray(),Runtime.Counters(),elapsed);
  if(selected is null)throw new InvalidOperationException("STUDY150_ABSTAIN: "+reason);return new(new(input.Time,selected.Tape.Actions[0],FreeActionSafety.SafeInHorizon,false,Array.Empty<FreeLearningCandidate>(),checked((int)(Runtime.Contacts-c0)),checked((int)(Runtime.Forecasts-f0))),elapsed);
 }
}
